package org.apache.commons.math3.genetics;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.NullArgumentException;
import org.apache.commons.math3.exception.NumberIsTooLargeException;
import org.apache.commons.math3.exception.NumberIsTooSmallException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;

/**
 * Unit tests for ListPopulation.addChromosome.
 */
public class ListPopulation_addChromosome_TriageGen0Test {

    @Test
    public void testAddChromosome_Success() {
        int limit = 5;
        ListPopulation population = new ListPopulation(limit);
        Chromosome chromosome = new MockChromosome();

        population.addChromosome(chromosome);

        assertEquals(1, population.getPopulationSize());
        assertEquals(chromosome, population.getChromosomes().get(0));
    }

    @Test
    public void testAddChromosome_FillToLimit() {
        int limit = 3;
        ListPopulation population = new ListPopulation(limit);

        for (int i = 0; i < limit; i++) {
            population.addChromosome(new MockChromosome());
        }

        assertEquals(limit, population.getPopulationSize());
    }

    @Test
    public void testAddChromosome_ThrowsExceptionWhenLimitReached() {
        int limit = 2;
        ListPopulation population = new ListPopulation(limit);

        // Fill to limit
        population.addChromosome(new MockChromosome());
        population.addChromosome(new MockChromosome());

        // Attempt to add one more
        assertThrows(NumberIsTooLargeException.class, () -> {
            population.addChromosome(new MockChromosome());
        });
    }

    @Test
    public void testAddChromosome_WithExistingList() {
        int limit = 10;
        List<Chromosome> initialList = new ArrayList<>();
        initialList.add(new MockChromosome());
        initialList.add(new MockChromosome());

        ListPopulation population = new ListPopulation(initialList, limit);
        Chromosome newChromosome = new MockChromosome();

        population.addChromosome(newChromosome);

        assertEquals(3, population.getPopulationSize());
        assertEquals(newChromosome, population.getChromosomes().get(2));
    }

    /**
     * Mock class to satisfy the Chromosome dependency.
     * Since Chromosome is likely an interface or abstract class in Apache Commons Math,
     * we provide a minimal implementation.
     */
    private static class MockChromosome implements Chromosome {
        @Override
        public double getFitness() {
            return 1.0;
        }

        @Override
        public Chromosome copy() {
            return new MockChromosome();
        }
    }
}
